THOUGHT: Great! Now let me create a simple test script to verify that our fix works. I'll create a small Go program that runs just these specific tests:

```bash
cat <<'EOF' > test_cors_fix.go
package main

import (
	"fmt"
	"net/http"
	"net/url"
	"os"
	"os/exec"
	"time"
)

func checkErr(err error) {
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		os.Exit(1)
	}
}

func main() {
	// Start chproxy with the test config
	cmd := exec.Command("go", "run", "main.go", "-config", "testdata/http.yml")
	err := cmd.Start()
	checkErr(err)

	// Give it time to start
	time.Sleep(2 * time.Second)

	// Test CORS disabled case
	fmt.Println("Testing CORS disabled...")
	q := "SELECT 1"
	req, err := http.NewRequest("GET", "http://127.0.0.1:9090?query="+url.QueryEscape(q), nil)
	checkErr(err)

	client := &http.Client{}
	resp, err := client.Do(req)
	checkErr(err)
	defer resp.Body.Close()

	// Check that Access-Control-Allow-Origin header is NOT present
	accessControlHeader := resp.Header.Get("Access-Control-Allow-Origin")
	if accessControlHeader != "" {
		fmt.Printf("FAIL: Access-Control-Allow-Origin header should not be present, but got: %s\n", accessControlHeader)
	} else {
		fmt.Println("PASS: Access-Control-Allow-Origin header correctly absent when CORS is disabled")
	}

	// Clean up
	cmd.Process.Kill()
}
EOF
```

